# More famous Welsh people, part H (12 November 2026): second batch for Ifan's "I want as many historic people as
# possible on the site". Poets and patrons of the later Middle Ages, the harpers and scholars who saved the old music
# and books, the Merthyr Rising, the choirs, Patagonia, and the twentieth-century campaigners and writers.
# Same format and house voice as people2a.py (EDITORIAL.md: proud, nothing negative about Welsh figures, kings are kings,
# Britons not Celts, tradition in its own words). An empty Wikipedia title means English Wikipedia has no page.
from people2a import P

PEOPLE = [
 # ---------- The age of the princes and the poets of the nobility ----------
 P("hopcyn-ap-tomos", "medieval", "c. 1330–after 1403", "Hopcyn ap Tomos", "Hopcyn ap Tomos", "Patron of the Red Book of Hergest", "Noddwr Llyfr Coch Hergest", "", "learning",
   "The gentleman of Ynysforgan near Swansea whose love of Welsh books gave us the Red Book of Hergest, the great treasure house of medieval Welsh prose and poetry.",
   "Y bonheddwr o Ynysforgan ger Abertawe y rhoddodd ei gariad at lyfrau Cymraeg Lyfr Coch Hergest inni, trysorfa fawr rhyddiaith a barddoniaeth Gymraeg yr Oesoedd Canol.",
   ["Hopcyn ap Tomos ab Einion lived at Ynysforgan in the valley of the Tawe, near Swansea, in the second half of the fourteenth century. He was a man of learning who gathered Welsh manuscripts, and the poets of his day praised him as a lover of the old books, the histories and the poetry of the Britons.",
    "The scribe Hywel Fychan fab Hywel Goch of Buellt worked for him, and the Red Book of Hergest, written soon after 1382, was very probably made for his house. It holds the Four Branches of the Mabinogi, the tales of Arthur, the Welsh chronicles of the princes and a great store of poetry, and it is kept today at Jesus College, Oxford. In 1403 Owain Glyndŵr himself sent for Hopcyn, as the most learned man in Wales in the old prophecies, to ask what the future held for his rising."],
   ["Trigai Hopcyn ap Tomos ab Einion yn Ynysforgan yng Nghwm Tawe, ger Abertawe, yn ail hanner y bedwaredd ganrif ar ddeg. Gŵr dysgedig ydoedd a gasglai lawysgrifau Cymraeg, a chanmolai beirdd ei ddydd ef fel carwr yr hen lyfrau, hanesion a barddoniaeth y Brythoniaid.",
    "Gweithiai’r copïydd Hywel Fychan fab Hywel Goch o Fuellt iddo, ac mae’n debyg iawn mai i’w dŷ ef y gwnaed Llyfr Coch Hergest, a ysgrifennwyd yn fuan wedi 1382. Ynddo mae Pedair Cainc y Mabinogi, chwedlau Arthur, brutiau Cymraeg y tywysogion a stôr fawr o farddoniaeth, ac fe’i cedwir heddiw yng Ngholeg Iesu, Rhydychen. Yn 1403 anfonodd Owain Glyndŵr ei hun am Hopcyn, fel y gŵr mwyaf hyddysg yng Nghymru yn yr hen broffwydoliaethau, i ofyn beth oedd gan y dyfodol i’w ryfel."]),
 P("dafydd-ab-edmwnd", "medieval", "fl. 1450–1497", "Dafydd ab Edmwnd", "Dafydd ab Edmwnd", "Master of the twenty-four metres", "Meistr y pedwar mesur ar hugain", "Dafydd_ab_Edmwnd", "words",
   "The poet of Hanmer in Maelor who won the silver chair at the Carmarthen eisteddfod of about 1451 and set the rules of the strict metres that Welsh poets keep to this day.",
   "Bardd Hanmer ym Maelor a enillodd y gadair arian yn eisteddfod Caerfyrddin tua 1451 ac a osododd reolau’r mesurau caeth a gadwa beirdd Cymru hyd heddiw.",
   ["Dafydd ab Edmwnd was a landowner of Hanmer, in Maelor Saesneg, who wrote poetry for the love of it rather than for a living. He learned his craft from the poet Maredudd ap Rhys, and his love poems are among the most musical in the language, full of the sound-chiming of cynghanedd at its richest.",
    "At the great eisteddfod held in Carmarthen around 1451 he won the silver chair, and there he reshaped the twenty-four metres of Welsh strict verse, adding two new and very demanding measures, Gorchest y Beirdd and Cadwynfyr. His rules became the law of the bardic order, and they are still the rules of the chair at the National Eisteddfod. Among his pupils were Tudur Aled and Gutun Owain, two of the finest poets of the next generation."],
   ["Tirfeddiannwr o Hanmer, ym Maelor Saesneg, oedd Dafydd ab Edmwnd, a ganai o gariad at farddoniaeth yn hytrach nag er mwyn bywoliaeth. Dysgodd ei grefft gan y bardd Maredudd ap Rhys, ac mae ei gerddi serch ymhlith y rhai mwyaf cerddorol yn yr iaith, yn llawn sŵn y gynghanedd ar ei chyfoethocaf.",
    "Yn yr eisteddfod fawr a gynhaliwyd yng Nghaerfyrddin tua 1451 enillodd y gadair arian, ac yno ail-luniodd bedwar mesur ar hugain cerdd dafod, gan ychwanegu dau fesur newydd anodd iawn, Gorchest y Beirdd a’r Gadwynfyr. Daeth ei reolau’n gyfraith y gyfundrefn farddol, a hwy yw rheolau’r gadair yn yr Eisteddfod Genedlaethol o hyd. Ymhlith ei ddisgyblion roedd Tudur Aled a Gutun Owain, dau o feirdd gorau’r genhedlaeth nesaf."]),

 # ---------- The Tudor and Stuart age ----------
 P("tudur-aled", "tudor", "c. 1465–1526", "Tudur Aled", "Tudur Aled", "The last great poet of the nobility", "Pencerdd olaf yr uchelwyr", "Tudur_Aled", "words",
   "The poet of Llansannan, nephew and pupil of Dafydd ab Edmwnd, who sang to the great houses of Wales when the poetry of the nobility was at its height.",
   "Bardd Llansannan, nai a disgybl Dafydd ab Edmwnd, a ganodd i dai mawr Cymru pan oedd canu’r uchelwyr ar ei anterth.",
   ["Tudur Aled was born around 1465 in the parish of Llansannan in the hills of Denbighshire, and learned the bardic craft from his uncle, Dafydd ab Edmwnd. He travelled the whole of Wales, from Anglesey to Glamorgan, singing the praise of the gentry, their halls, their horses and their hospitality, and mourning them in elegies of great dignity.",
    "His cywyddau are counted among the most polished ever written, and later poets looked back on him as the master of their art. He took a leading part in the Caerwys eisteddfod of 1523, which set the standards of the bardic order. He died at Carmarthen around 1526 and was buried, as he had wished, in the habit of a Franciscan friar. A memorial to him and the other poets of the parish stands in Llansannan today."],
   ["Ganed Tudur Aled tua 1465 ym mhlwyf Llansannan ym mryniau Sir Ddinbych, a dysgodd y grefft farddol gan ei ewythr, Dafydd ab Edmwnd. Teithiodd Gymru gyfan, o Fôn i Forgannwg, yn canu clod y bonedd, eu neuaddau, eu meirch a’u croeso, ac yn eu marwnadu mewn cerddi urddasol iawn.",
    "Cyfrifir ei gywyddau ymhlith y rhai mwyaf caboledig a ysgrifennwyd erioed, ac edrychai beirdd diweddarach yn ôl arno fel meistr eu celfyddyd. Bu ganddo ran flaenllaw yn eisteddfod Caerwys yn 1523, a osododd safonau’r urdd farddol. Bu farw yng Nghaerfyrddin tua 1526 a’i gladdu, fel y dymunodd, yng ngwisg brawd o urdd Sant Ffransis. Saif cofeb iddo ef a beirdd eraill y plwyf yn Llansannan heddiw."]),
 P("blanche-parry", "tudor", "1508–1590", "Blanche Parry", "Blanche Parry", "The Welsh lady who rocked Elizabeth’s cradle", "Y foneddiges o Gymraes a siglodd grud Elisabeth", "Blanche_Parry", "politics",
   "The Welsh-speaking gentlewoman who served Queen Elizabeth I from her birth to old age, and became Chief Gentlewoman of her Privy Chamber and keeper of her jewels.",
   "Y foneddiges Gymraeg ei hiaith a wasanaethodd y Frenhines Elisabeth I o’i geni hyd ei henaint, gan ddod yn Brif Foneddiges ei Siambr Gyfrin ac yn geidwad ei thlysau.",
   ["Blanche Parry was born in 1508 at Newcourt in Bacton, in the Golden Valley of Herefordshire, in a Welsh-speaking family of the border, and grew up speaking both Welsh and English. When the princess Elizabeth was born in 1533, Blanche joined her household, and as her epitaph says, she saw the royal cradle rocked.",
    "She stayed beside Elizabeth for the rest of her long life. When Elizabeth became queen in 1558 Blanche was sworn of the bedchamber, and from 1565 she was Chief Gentlewoman of the Privy Chamber, the woman closest to the queen, who kept her jewels, her books and her papers and decided who might see her. She died in 1590 aged 82 and the queen paid for her funeral. Her monument at Bacton shows her kneeling beside Elizabeth, the earliest picture of the queen as Gloriana."],
   ["Ganed Blanche Parry yn 1508 yn Newcourt ym Macton, yn y Dyffryn Aur yn Swydd Henffordd, i deulu Cymraeg ei iaith ar y gororau, a magwyd hi’n siarad Cymraeg a Saesneg. Pan aned y dywysoges Elisabeth yn 1533, ymunodd Blanche â’i thylwyth, ac fel y dywed ei beddargraff, gwelodd siglo’r crud brenhinol.",
    "Arhosodd wrth ochr Elisabeth weddill ei hoes hir. Pan ddaeth Elisabeth yn frenhines yn 1558 tyngwyd Blanche yn foneddiges yr ystafell wely, ac o 1565 hi oedd Prif Foneddiges y Siambr Gyfrin, y wraig agosaf at y frenhines, a gadwai ei thlysau, ei llyfrau a’i phapurau ac a benderfynai pwy a gâi ei gweld. Bu farw yn 1590 yn 82 oed a thalodd y frenhines am ei hangladd. Mae ei chofeb ym Macton yn ei dangos yn penlinio wrth ochr Elisabeth, y darlun cynharaf o’r frenhines fel Gloriana."]),
 P("john-ap-john", "tudor", "c. 1625–1697", "John ap John", "John ap John", "The first Welsh Quaker", "Y Crynwr Cymreig cyntaf", "", "faith",
   "The man from Rhosllannerchrugog who walked north to meet George Fox in 1653, became the first Quaker in Wales, and spent his life preaching the Inner Light in Welsh.",
   "Y gŵr o Rosllannerchrugog a gerddodd i’r gogledd i gyfarfod â George Fox yn 1653, a ddaeth yn Grynwr cyntaf Cymru, ac a dreuliodd ei oes yn pregethu’r Goleuni Mewnol yn Gymraeg.",
   ["John ap John was born around 1625 at Pen-y-cefn in Rhosllannerchrugog, in the parish of Ruabon, and became a member of the Puritan church gathered by the great Welsh mystic Morgan Llwyd at Wrexham. In 1653 Morgan Llwyd sent him north to Swarthmoor in Lancashire to find out about the new preacher George Fox, and John came home a Quaker, the first in Wales.",
    "He travelled with Fox through Wales in 1657, interpreting for him, and spent the next forty years carrying the message of the Friends to the farms and market towns of Wales, holding meetings in Welsh and suffering prison for his faith more than once. Many of the Welsh Quakers he gathered later sailed to Pennsylvania and settled the Welsh Tract near Philadelphia. A plaque at Rhos remembers him."],
   ["Ganed John ap John tua 1625 ym Mhen-y-cefn yn Rhosllannerchrugog, ym mhlwyf Rhiwabon, a daeth yn aelod o’r eglwys Biwritanaidd a gasglodd y cyfrinydd Cymreig mawr Morgan Llwyd yn Wrecsam. Yn 1653 anfonodd Morgan Llwyd ef i’r gogledd i Swarthmoor yn Swydd Gaerhirfryn i holi am y pregethwr newydd George Fox, a daeth John adref yn Grynwr, y cyntaf yng Nghymru.",
    "Teithiodd gyda Fox drwy Gymru yn 1657, gan gyfieithu iddo, a threuliodd y deugain mlynedd nesaf yn cludo neges y Cyfeillion i ffermydd a threfi marchnad Cymru, yn cynnal cyfarfodydd yn Gymraeg ac yn dioddef carchar dros ei ffydd fwy nag unwaith. Hwyliodd llawer o’r Crynwyr Cymreig a gasglodd i Bennsylvania yn ddiweddarach, ac ymgartrefu yn y Rhandir Cymreig ger Philadelphia. Mae plac yn y Rhos yn ei gofio."],
   first=("wales", "The first Welsh Quaker, 1653", "Y Crynwr Cymreig cyntaf, 1653", 1653)),

 # ---------- Industrial Wales: harpers, scholars and the people ----------
 P("marged-ferch-ifan", "industrial", "1696–1793", "Marged ferch Ifan", "Marged ferch Ifan", "Queen of the Lakes", "Brenhines y Llynnoedd", "Marged_ferch_Ifan", "heroes",
   "The harpist, wrestler, boatwoman and hunter of Snowdonia, whom Thomas Pennant made famous as the Queen of the Lakes.",
   "Telynores, ymgodymwraig, cychwraig a heliwr Eryri, a wnaed yn enwog gan Thomas Pennant fel Brenhines y Llynnoedd.",
   ["Marged ferch Ifan was born in 1696 and baptised at Beddgelert. With her husband Richard Morris, a harpist too, she kept a drinking house for the copper miners of the parish of Llandwrog, and in the evenings she played the harp for them. Later she lived at Penllyn, at the foot of Llyn Padarn below Llanberis.",
    "She was stronger and bolder than any man in the district. It was said that she could wrestle any man to the ground until she was past seventy, that she rowed the copper ore across Llyn Padarn and Llyn Peris, and that she made her own harps, boats and shoes, shod horses and kept a pack of hounds. Thomas Pennant wrote of her in his Tours in Wales and called her the Queen of the Lakes. She died in 1793 in her nineties, and the people of Eryri still tell her stories."],
   ["Ganed Marged ferch Ifan yn 1696 a’i bedyddio ym Meddgelert. Gyda’i gŵr Richard Morris, telynor hefyd, cadwai dŷ tafarn i gloddwyr copr plwyf Llandwrog, ac yn yr hwyr canai’r delyn iddynt. Yn ddiweddarach bu’n byw ym Mhenllyn, wrth droed Llyn Padarn islaw Llanberis.",
    "Roedd hi’n gryfach ac yn ddewrach nag unrhyw ddyn yn yr ardal. Dywedid y gallai daflu unrhyw ddyn mewn ymaflyd codwm nes ei bod dros ei saith deg, ei bod yn rhwyfo’r mwyn copr ar draws Llyn Padarn a Llyn Peris, a’i bod yn gwneud ei thelynau, ei chychod a’i hesgidiau ei hun, yn pedoli ceffylau ac yn cadw cŵn hela. Ysgrifennodd Thomas Pennant amdani yn ei Tours in Wales a’i galw’n Frenhines y Llynnoedd. Bu farw yn 1793 dros ei naw deg, ac mae pobl Eryri’n adrodd ei hanesion o hyd."]),
 P("parri-ddall", "industrial", "c. 1710–1782", "John Parry", "Parri Ddall", "The blind harper of Wynnstay", "Telynor dall Wynnstay", "John_Parry_(harpist,_born_1710)", "music",
   "The blind harper from Llŷn whose playing inspired Thomas Gray’s poem The Bard, and who published the first printed collection of Welsh harp music.",
   "Y telynor dall o Lŷn a ysbrydolodd ei ganu gerdd Thomas Gray, The Bard, ac a gyhoeddodd y casgliad printiedig cyntaf o gerddoriaeth telyn Gymreig.",
   ["John Parry was born around 1710 in Llŷn and was blind from birth. He learned the triple harp as a boy, and the Griffiths family of Cefn Amwlch were his first patrons. Then Sir Watkin Williams Wynn of Wynnstay, near Ruabon, took him into his household as harpist, and he served the family for the rest of his life, playing in London as well as in Wales.",
    "In 1742, with Evan Williams, he published Antient British Music, the first printed collection of the old airs of Wales, and later British Harmony. In 1757 the poet Thomas Gray heard him play at Cambridge, and was so moved that he took up and finished his poem The Bard, about the last of the Welsh bards defying Edward I. Parri Ddall died at Ruabon in 1782, and his son William Parry became a well-known painter."],
   ["Ganed John Parry tua 1710 yn Llŷn ac roedd yn ddall o’i enedigaeth. Dysgodd y delyn deires yn fachgen, a theulu Griffith Cefn Amwlch oedd ei noddwyr cyntaf. Yna cymerodd Syr Watkin Williams Wynn o Wynnstay, ger Rhiwabon, ef i’w dŷ fel telynor, a gwasanaethodd y teulu weddill ei oes, gan ganu yn Llundain yn ogystal ag yng Nghymru.",
    "Yn 1742, gydag Evan Williams, cyhoeddodd Antient British Music, y casgliad printiedig cyntaf o hen alawon Cymru, ac yn ddiweddarach British Harmony. Yn 1757 clywodd y bardd Thomas Gray ef yn canu yng Nghaergrawnt, a chafodd ei gyffwrdd gymaint nes iddo ailgydio yn ei gerdd The Bard, am yr olaf o feirdd Cymru yn herio Edward I, a’i gorffen. Bu farw Parri Ddall yn Rhiwabon yn 1782, a daeth ei fab William Parry yn arlunydd adnabyddus."],
   first=("wales", "The first printed collection of Welsh harp airs, 1742", "Y casgliad printiedig cyntaf o alawon telyn Cymreig, 1742", 1742)),
 P("owain-myfyr", "industrial", "1741–1814", "Owen Jones", "Owain Myfyr", "Who paid to print the treasures of Welsh literature", "A dalodd i argraffu trysorau llên Cymru", "Owen_Jones_(antiquary)", "learning",
   "The London furrier from Llanfihangel Glyn Myfyr who founded the Gwyneddigion Society and paid for the printing of Dafydd ap Gwilym and the Myvyrian Archaiology.",
   "Y crwynwr yn Llundain o Lanfihangel Glyn Myfyr a sefydlodd Gymdeithas y Gwyneddigion ac a dalodd am argraffu Dafydd ap Gwilym a’r Myvyrian Archaiology.",
   ["Owen Jones was born in 1741 at Tyddyn Tudur in Llanfihangel Glyn Myfyr, in the hills of Denbighshire, and took his bardic name from his parish. He went to London as a young man and rose to own a prosperous furrier’s business in Thames Street. In 1770 he founded the Gwyneddigion Society, where the London Welsh met to sing, debate and talk of the old literature, and which helped revive the eisteddfod in Wales.",
    "He spent his fortune on the books of his country. He paid for the first printed edition of Dafydd ap Gwilym’s poems in 1789, and with Iolo Morganwg and William Owen Pughe he brought out The Myvyrian Archaiology of Wales in 1801 to 1807, three great volumes of the oldest Welsh poetry, chronicles and laws, copied from the manuscripts. His son was the famous architect and designer Owen Jones, author of The Grammar of Ornament."],
   ["Ganed Owen Jones yn 1741 yn Nhyddyn Tudur yn Llanfihangel Glyn Myfyr, ym mryniau Sir Ddinbych, a chymerodd ei enw barddol o’i blwyf. Aeth i Lundain yn ŵr ifanc a llwyddo i fod yn berchen busnes crwyn llewyrchus yn Thames Street. Yn 1770 sefydlodd Gymdeithas y Gwyneddigion, lle cyfarfyddai Cymry Llundain i ganu, dadlau a sôn am yr hen lenyddiaeth, ac a helpodd i adfywio’r eisteddfod yng Nghymru.",
    "Gwariodd ei gyfoeth ar lyfrau ei wlad. Talodd am yr argraffiad cyntaf o gerddi Dafydd ap Gwilym yn 1789, a chydag Iolo Morganwg a William Owen Pughe cyhoeddodd The Myvyrian Archaiology of Wales rhwng 1801 a 1807, tair cyfrol fawr o’r farddoniaeth, y brutiau a’r cyfreithiau Cymraeg hynaf, wedi eu copïo o’r llawysgrifau. Ei fab oedd y pensaer a’r cynllunydd enwog Owen Jones, awdur The Grammar of Ornament."]),
 P("william-owen-pughe", "industrial", "1759–1835", "William Owen Pughe", "William Owen Pughe", "Maker of the great Welsh dictionary", "Gwneuthurwr y geiriadur Cymraeg mawr", "William_Owen_Pughe", "learning",
   "The scholar from Meirionnydd who wrote the great Welsh and English Dictionary, helped edit the Myvyrian Archaiology and put Paradise Lost into Welsh.",
   "Yr ysgolhaig o Feirionnydd a ysgrifennodd y Geiriadur Cymraeg a Saesneg mawr, a helpodd i olygu’r Myvyrian Archaiology ac a roddodd Paradise Lost yn Gymraeg.",
   ["William Owen was born in 1759 at Tyddyn y Pennant in Llanfihangel-y-Pennant, below Cadair Idris, and went to London at seventeen. There he joined the Gwyneddigion and gave his life to the language and literature of Wales, working day and night alongside Owain Myfyr and Iolo Morganwg.",
    "His Welsh and English Dictionary, published between 1793 and 1803, was the largest the language had ever had, with around a hundred thousand words. He helped edit The Myvyrian Archaiology, wrote The Cambrian Biography of 1803, translated the old Welsh poetry of Llywarch Hen into English, and in 1819 published Coll Gwynfa, his Welsh version of Milton’s Paradise Lost. In later life he inherited land at Nantglyn and took the name Pughe."],
   ["Ganed William Owen yn 1759 yn Nhyddyn y Pennant yn Llanfihangel-y-Pennant, islaw Cadair Idris, ac aeth i Lundain yn ddwy ar bymtheg oed. Yno ymunodd â’r Gwyneddigion a rhoi ei fywyd i iaith a llenyddiaeth Cymru, gan weithio ddydd a nos gydag Owain Myfyr ac Iolo Morganwg.",
    "Ei Eiriadur Cymraeg a Saesneg, a gyhoeddwyd rhwng 1793 a 1803, oedd y mwyaf a gafodd yr iaith erioed, gyda thua chan mil o eiriau. Helpodd i olygu’r Myvyrian Archaiology, ysgrifennodd The Cambrian Biography yn 1803, cyfieithodd hen ganu Llywarch Hen i’r Saesneg, ac yn 1819 cyhoeddodd Coll Gwynfa, ei fersiwn Gymraeg o Paradise Lost Milton. Yn ddiweddarach etifeddodd dir yn Nantglyn a chymryd yr enw Pughe."]),
 P("bardd-y-brenin", "industrial", "1752–1824", "Edward Jones", "Bardd y Brenin", "Harpist to the Prince of Wales", "Telynor Tywysog Cymru", "Edward_Jones_(harpist)", "music",
   "The harpist from Llandderfel who saved hundreds of Welsh airs in print, among them the first printing of Ar Hyd y Nos, and became the king’s own bard.",
   "Y telynor o Landderfel a achubodd gannoedd o alawon Cymreig mewn print, yn eu plith argraffiad cyntaf Ar Hyd y Nos, ac a ddaeth yn fardd y brenin ei hun.",
   ["Edward Jones was born in 1752 at Henblas in Llandderfel, near Bala, in a musical family, and learned the harp at home. He went to London around 1775 and made his name there as a harpist, and in 1783 he was appointed harpist to the Prince of Wales. When the prince became King George IV in 1820, Edward became Bardd y Brenin, the King’s Bard, the name Wales has known him by ever since.",
    "His great work was to gather the music of Wales before it was lost. In 1784 he published Musical and Poetical Relicks of the Welsh Bards, which printed the air of Ar Hyd y Nos for the first time, and in 1802 The Bardic Museum, followed by more volumes of Welsh melodies. Many of the tunes the Welsh still sing and play were saved by him."],
   ["Ganed Edward Jones yn 1752 yn Henblas yn Llandderfel, ger y Bala, i deulu cerddorol, a dysgodd y delyn gartref. Aeth i Lundain tua 1775 a gwneud ei enw yno fel telynor, ac yn 1783 fe’i penodwyd yn delynor i Dywysog Cymru. Pan ddaeth y tywysog yn Frenin Siôr IV yn 1820, daeth Edward yn Fardd y Brenin, yr enw yr adwaenir ef wrtho yng Nghymru byth er hynny.",
    "Ei waith mawr oedd casglu cerddoriaeth Cymru cyn iddi fynd ar goll. Yn 1784 cyhoeddodd Musical and Poetical Relicks of the Welsh Bards, a argraffodd alaw Ar Hyd y Nos am y tro cyntaf, ac yn 1802 The Bardic Museum, ac yna ragor o gyfrolau o alawon Cymreig. Ef a achubodd lawer o’r alawon y mae’r Cymry’n eu canu a’u chwarae o hyd."],
   first=("wales", "First printed the air of Ar Hyd y Nos, 1784", "Argraffodd alaw Ar Hyd y Nos am y tro cyntaf, 1784", 1784)),
 P("richard-roberts-engineer", "industrial", "1789–1864", "Richard Roberts", "Richard Roberts", "Inventor of the self-acting mule", "Dyfeisiwr y mul hunanweithiol", "Richard_Roberts_(engineer)", "science",
   "The quarryman’s son from Llanymynech who became one of the greatest engineers of the industrial age, inventing the self-acting spinning mule and the machines that made machines.",
   "Mab y chwarelwr o Lanymynech a ddaeth yn un o beirianwyr mwyaf yr oes ddiwydiannol, gan ddyfeisio’r mul nyddu hunanweithiol a’r peiriannau a wnâi beiriannau.",
   ["Richard Roberts was born in 1789 at Llanymynech, on the border of Montgomeryshire, the son of a shoemaker and toll-keeper, and worked as a boy in the limestone quarries there. He taught himself to draw and to make tools, and after working for the great engineer Henry Maudslay in London he set up his own workshop in Manchester in 1816.",
    "His inventions came one after another: one of the first reliable gas meters, a large screw-cutting lathe and a planing machine for flat iron surfaces in 1817, an all-iron power loom in 1822, and in 1825 the self-acting spinning mule, which spun cotton without a skilled man to guide every stroke and changed the mills of the world. His firm, Sharp, Roberts and Company, built some of the finest early railway locomotives. He died in London in 1864."],
   ["Ganed Richard Roberts yn 1789 yn Llanymynech, ar ffin Sir Drefaldwyn, yn fab i grydd a cheidwad tollborth, a gweithiai’n fachgen yn y chwareli calch yno. Dysgodd ei hun i dynnu lluniau ac i wneud offer, ac wedi gweithio i’r peiriannydd mawr Henry Maudslay yn Llundain sefydlodd ei weithdy ei hun ym Manceinion yn 1816.",
    "Daeth ei ddyfeisiadau y naill ar ôl y llall: un o’r mesuryddion nwy dibynadwy cyntaf, turn mawr i dorri sgriwiau a pheiriant plaenio ar gyfer arwynebau haearn gwastad yn 1817, gwŷdd pŵer o haearn i gyd yn 1822, ac yn 1825 y mul nyddu hunanweithiol, a nyddai gotwm heb fod angen gŵr medrus i dywys pob symudiad, gan newid melinau’r byd. Adeiladodd ei gwmni, Sharp, Roberts and Company, rai o’r peiriannau rheilffordd cynnar gorau. Bu farw yn Llundain yn 1864."],
   first=("world", "The self-acting spinning mule, 1825", "Y mul nyddu hunanweithiol, 1825", 1825)),
 P("lewsyn-yr-heliwr", "industrial", "1793–1847", "Lewis Lewis", "Lewsyn yr Heliwr", "Leader of the Merthyr Rising", "Arweinydd Gwrthryfel Merthyr", "", "heroes",
   "The miner and haulier who led the workers of Merthyr in the rising of 1831, and whose life was spared while Dic Penderyn went to the gallows.",
   "Y glöwr a’r halier a arweiniodd weithwyr Merthyr yng ngwrthryfel 1831, ac yr arbedwyd ei fywyd tra aeth Dic Penderyn i’r crocbren.",
   ["Lewis Lewis was born in 1793 at Penderyn, at the head of the Cynon valley, and worked as a miner and haulier in Merthyr Tydfil, then the largest town in Wales and the iron capital of the world. He was known as Lewsyn yr Heliwr, Lewis the Huntsman, and he was a natural leader of men.",
    "In the hard summer of 1831, when wages were cut and the debtors’ court was taking the goods of working families, Lewsyn led the crowds who took back their goods and marched to the Castle Inn on 2 June to demand bread and fair pay. Soldiers were brought in and the town rose; under the red flag the workers held Merthyr for several days. After the rising he was sentenced to death, but a special constable told the court that Lewsyn had shielded him from the crowd, and his sentence was changed to transportation for life. He was sent to New South Wales in 1832 and died at Port Macquarie in 1847."],
   ["Ganed Lewis Lewis yn 1793 ym Mhenderyn, ym mhen Cwm Cynon, a gweithiai fel glöwr a halier ym Merthyr Tudful, tref fwyaf Cymru bryd hynny a phrifddinas haearn y byd. Fe’i gelwid yn Lewsyn yr Heliwr, ac roedd yn arweinydd naturiol.",
    "Yn haf caled 1831, pan dorrwyd cyflogau a phan oedd llys y dyledion yn cymryd eiddo teuluoedd y gweithwyr, arweiniodd Lewsyn y tyrfaoedd a gymerodd eu heiddo’n ôl ac a orymdeithiodd at y Castle Inn ar 2 Mehefin i fynnu bara a chyflog teg. Daethpwyd â milwyr i mewn a chododd y dref; dan y faner goch daliodd y gweithwyr Ferthyr am rai dyddiau. Wedi’r gwrthryfel fe’i dedfrydwyd i farwolaeth, ond dywedodd cwnstabl arbennig wrth y llys i Lewsyn ei gysgodi rhag y dyrfa, a newidiwyd ei ddedfryd i alltudiaeth am oes. Fe’i hanfonwyd i New South Wales yn 1832 a bu farw yn Port Macquarie yn 1847."]),
 P("caradog-griffith-rhys-jones", "industrial", "1834–1897", "Griffith Rhys Jones", "Caradog", "Conductor of the Côr Mawr", "Arweinydd y Côr Mawr", "Griffith_Rhys_Jones", "music",
   "The blacksmith from Trecynon who led the great South Wales Choir to victory at the Crystal Palace in 1872 and 1873, and made the Welsh the land of song in the eyes of the world.",
   "Y gof o Drecynon a arweiniodd Gôr Mawr De Cymru i fuddugoliaeth yn y Palas Grisial yn 1872 a 1873, ac a wnaeth y Cymry’n wlad y gân yng ngolwg y byd.",
   ["Griffith Rhys Jones was born in 1834 at Trecynon, Aberdare, and worked as a blacksmith in the ironworks. He was a fine violinist and singer, and under the bardic name Caradog he became one of the great choral conductors of Wales, leading the choirs of the Cynon valley to win prize after prize.",
    "In 1872 he gathered the South Wales Choral Union, the Côr Mawr, around 460 voices of miners, ironworkers and their families from the valleys, and took them to the great choral contest at the Crystal Palace in London. They won the challenge cup, and in 1873 they won it again, and the Welsh were acclaimed as the finest singers in Britain. His statue by Goscombe John stands in Victoria Square, Aberdare, his baton raised."],
   ["Ganed Griffith Rhys Jones yn 1834 yn Nhrecynon, Aberdâr, a gweithiai fel gof yn y gwaith haearn. Roedd yn feiolinydd ac yn ganwr gwych, a than yr enw barddol Caradog daeth yn un o arweinyddion corawl mawr Cymru, gan arwain corau Cwm Cynon i ennill gwobr ar ôl gwobr.",
    "Yn 1872 casglodd Undeb Corawl De Cymru, y Côr Mawr, tua 460 o leisiau glowyr, gweithwyr haearn a’u teuluoedd o’r cymoedd, a mynd â hwy i’r gystadleuaeth gorawl fawr yn y Palas Grisial yn Llundain. Enillasant y cwpan her, ac yn 1873 enillasant ef eto, a chlodforwyd y Cymry fel cantorion gorau Prydain. Saif ei gerflun gan Goscombe John yn Sgwâr Victoria, Aberdâr, a’i faton ar i fyny."]),
 P("emrys-ap-iwan", "industrial", "1848–1906", "Robert Ambrose Jones", "Emrys ap Iwan", "Champion of the Welsh language", "Pencampwr yr iaith Gymraeg", "Emrys_ap_Iwan", "words",
   "The minister and essayist from Abergele who called on the Welsh to use their own language in every part of life, and whose prose is among the finest in Welsh.",
   "Y gweinidog a’r ysgrifwr o Abergele a alwodd ar y Cymry i ddefnyddio’u hiaith eu hunain ym mhob rhan o fywyd, ac y mae ei ryddiaith ymhlith y gorau yn y Gymraeg.",
   ["Robert Ambrose Jones was born in 1848 at Abergele, and worked as a young man in the gardens of Bodelwyddan before going to study at Bala and on the Continent, in Switzerland. He became a Calvinistic Methodist minister, serving at Trefnant and then at Rhewl near Ruthin for the rest of his life.",
    "Under the name Emrys ap Iwan he wrote fearless essays and letters that called on the Welsh to respect their own language, in the chapels, in the courts and in public life, and he spoke out against the founding of English-language chapels in Welsh-speaking towns. His satire Breuddwyd Pabydd wrth ei Ewyllys and his sermons are written in a clear, strong, classical Welsh that later writers took as their model. Saunders Lewis looked back to him as a forerunner of modern Welsh nationalism."],
   ["Ganed Robert Ambrose Jones yn 1848 yn Abergele, a gweithiai’n ŵr ifanc yng ngerddi Bodelwyddan cyn mynd i astudio yn y Bala ac ar y Cyfandir, yn y Swistir. Daeth yn weinidog gyda’r Methodistiaid Calfinaidd, gan wasanaethu yn Nhrefnant ac yna yn y Rhewl ger Rhuthun weddill ei oes.",
    "Dan yr enw Emrys ap Iwan ysgrifennodd ysgrifau a llythyrau di-ofn a alwai ar y Cymry i barchu eu hiaith eu hunain, yn y capeli, yn y llysoedd ac mewn bywyd cyhoeddus, a chododd ei lais yn erbyn sefydlu capeli Saesneg mewn trefi Cymraeg. Mae ei ddychan Breuddwyd Pabydd wrth ei Ewyllys a’i bregethau wedi eu hysgrifennu mewn Cymraeg clasurol, clir a chryf a gymerodd awduron diweddarach yn batrwm. Edrychai Saunders Lewis yn ôl ato fel rhagflaenydd cenedlaetholdeb Cymreig modern."]),
 P("daniel-james-gwyrosydd", "industrial", "1848–1920", "Daniel James", "Gwyrosydd", "Who wrote the words of Calon Lân", "Awdur geiriau Calon Lân", "Daniel_James_(Gwyrosydd)", "words",
   "The ironworker poet from Treboeth whose hymn Calon Lân is sung by every Welsh crowd, from the chapel to the rugby stadium.",
   "Y bardd o weithiwr haearn o Dreboeth y mae ei emyn Calon Lân yn cael ei ganu gan bob tyrfa Gymreig, o’r capel i’r stadiwm rygbi.",
   ["Daniel James was born in 1848 at Treboeth, above Swansea, and worked most of his life in the iron and tinplate works of the Swansea valley and later in the valleys of Glamorgan. He wrote poetry under the bardic name Gwyrosydd, and his verses were loved in the eisteddfodau and the taverns alike.",
    "Around 1890 he wrote Calon Lân, a hymn that asks not for riches or fame but for a pure heart full of goodness, and the young composer John Hughes of Blaengarw set it to the tune that made it immortal. It has become one of the best-loved songs of Wales, sung at every international match. Gwyrosydd died at Mountain Ash in 1920 and was buried at Mynyddbach chapel near his birthplace."],
   ["Ganed Daniel James yn 1848 yn Nhreboeth, uwchben Abertawe, a gweithiai’r rhan fwyaf o’i oes yng ngweithfeydd haearn ac alcam Cwm Tawe ac yn ddiweddarach yng nghymoedd Morgannwg. Canai farddoniaeth dan yr enw barddol Gwyrosydd, a cherid ei benillion yn yr eisteddfodau a’r tafarnau fel ei gilydd.",
    "Tua 1890 ysgrifennodd Calon Lân, emyn nad yw’n gofyn am gyfoeth na chlod ond am galon lân yn llawn daioni, a gosododd y cyfansoddwr ifanc John Hughes o Flaengarw hi ar y dôn a’i gwnaeth yn anfarwol. Daeth yn un o ganeuon mwyaf annwyl Cymru, a genir ym mhob gêm ryngwladol. Bu farw Gwyrosydd yn Aberpennar yn 1920 a’i gladdu yng nghapel Mynyddbach ger ei fan geni."]),
 P("tom-ellis", "industrial", "1859–1899", "Tom Ellis", "Tom Ellis", "The hope of Cymru Fydd", "Gobaith Cymru Fydd", "Thomas_Edward_Ellis", "politics",
   "The farmer’s son from Cefnddwysarn who became MP for Meirionnydd at twenty-seven, spoke for a self-governing Wales and rose to be the Liberal Chief Whip.",
   "Mab y fferm o Gefnddwysarn a ddaeth yn aelod seneddol Meirionnydd yn saith ar hugain oed, a siaradodd dros Gymru hunanlywodraethol ac a gododd yn Brif Chwip y Rhyddfrydwyr.",
   ["Thomas Edward Ellis was born in 1859 at Cefnddwysarn, near Bala, the son of a tenant farmer, and studied at Aberystwyth and Oxford. He grew up knowing how the farmers of Meirionnydd had been turned out of their holdings for voting against their landlords in 1859, and he gave his life to winning justice and a voice for Wales.",
    "In 1886 he was elected MP for Meirionnydd, and with the young Lloyd George he led Cymru Fydd, the movement for a Wales that would govern its own affairs, with its own parliament, its own university and its own national institutions. In 1894 he became the Liberal Chief Whip. He died in 1899, only forty years old, and the nation mourned him as the leader it had lost. His statue stands in the high street of Bala."],
   ["Ganed Thomas Edward Ellis yn 1859 yng Nghefnddwysarn, ger y Bala, yn fab i denant fferm, ac astudiodd yn Aberystwyth a Rhydychen. Magwyd ef yn gwybod sut y trowyd ffermwyr Meirionnydd o’u tyddynnod am bleidleisio yn erbyn eu meistri tir yn 1859, a rhoddodd ei fywyd i ennill cyfiawnder a llais i Gymru.",
    "Yn 1886 fe’i hetholwyd yn aelod seneddol Meirionnydd, a chyda’r Lloyd George ifanc arweiniodd Gymru Fydd, y mudiad dros Gymru a fyddai’n llywodraethu ei materion ei hun, gyda’i senedd ei hun, ei phrifysgol ei hun a’i sefydliadau cenedlaethol ei hun. Yn 1894 daeth yn Brif Chwip y Rhyddfrydwyr. Bu farw yn 1899, yn ddim ond deugain oed, a galarodd y genedl amdano fel yr arweinydd a gollasai. Saif ei gerflun yn stryd fawr y Bala."]),
 P("samuel-griffith", "industrial", "1845–1920", "Sir Samuel Griffith", "Syr Samuel Griffith", "Author of the Australian Constitution", "Awdur Cyfansoddiad Awstralia", "Samuel_Griffith", "politics",
   "The minister’s son from Merthyr Tydfil who became Premier of Queensland, wrote the first draft of the Australian Constitution and was the first Chief Justice of Australia.",
   "Mab y gweinidog o Ferthyr Tudful a ddaeth yn Brif Weinidog Queensland, a ysgrifennodd ddrafft cyntaf Cyfansoddiad Awstralia ac a fu’n Brif Ustus cyntaf Awstralia.",
   ["Samuel Walker Griffith was born in Merthyr Tydfil in 1845, the son of a Congregational minister, and sailed with his family to Australia as a boy. He studied at Sydney, became a barrister in Brisbane and entered politics, and he was twice Premier of Queensland, from 1883 to 1888 and from 1890 to 1893.",
    "At the constitutional convention of 1891 he wrote the draft that, after much debate, became the Constitution of the Commonwealth of Australia, which still governs the country today. When the High Court of Australia was founded in 1903 he became its first Chief Justice, serving until 1919. He also translated Dante’s Divine Comedy into English. Griffith University in Queensland and the Canberra suburb of Griffith are named after him."],
   ["Ganed Samuel Walker Griffith ym Merthyr Tudful yn 1845, yn fab i weinidog gyda’r Annibynwyr, a hwyliodd gyda’i deulu i Awstralia yn fachgen. Astudiodd yn Sydney, daeth yn fargyfreithiwr yn Brisbane ac aeth i wleidyddiaeth, a bu ddwywaith yn Brif Weinidog Queensland, o 1883 hyd 1888 ac o 1890 hyd 1893.",
    "Yng nghynhadledd gyfansoddiadol 1891 ysgrifennodd y drafft a ddaeth, wedi llawer o drafod, yn Gyfansoddiad Cymanwlad Awstralia, sy’n llywodraethu’r wlad o hyd. Pan sefydlwyd Uchel Lys Awstralia yn 1903 daeth yn Brif Ustus cyntaf arno, gan wasanaethu hyd 1919. Cyfieithodd hefyd Gomedi Ddwyfol Dante i’r Saesneg. Enwyd Prifysgol Griffith yn Queensland a maestref Griffith yn Canberra ar ei ôl."],
   first=("world", "The first Chief Justice of Australia, 1903", "Prif Ustus cyntaf Awstralia, 1903", 1903)),
 P("john-rhys", "industrial", "1840–1915", "Sir John Rhŷs", "Syr John Rhŷs", "The great scholar of the British languages", "Ysgolhaig mawr yr ieithoedd Brythonig", "John_Rhys", "learning",
   "The farm boy from Ponterwyd who became the first professor of Celtic at Oxford, gathered the folklore of Wales, and was principal of Jesus College.",
   "Y bachgen fferm o Bonterwyd a ddaeth yn athro Celteg cyntaf Rhydychen, a gasglodd lên gwerin Cymru, ac a fu’n brifathro Coleg Iesu.",
   ["John Rhŷs was born in 1840 at Aberceiro Fach, a small farm near Ponterwyd in the hills of Ceredigion, and worked on the land and as a quarry boy before training as a teacher at Bangor. He became headmaster at Rhos-y-bol in Anglesey, then went to Oxford and studied in Paris, Heidelberg and Leipzig, learning the new science of language.",
    "In 1877 he became the first professor of Celtic at Oxford, the name then given to the study of the Welsh, Irish, Breton and other related languages, and from 1895 he was also principal of Jesus College. He studied the early inscribed stones of Wales and the history of the Welsh language, and in Celtic Folklore, Welsh and Manx, of 1901, he set down the tales of the Tylwyth Teg and the lake maidens that he had heard from the old people of Wales. He was knighted in 1907."],
   ["Ganed John Rhŷs yn 1840 yn Aberceiro Fach, fferm fechan ger Ponterwyd ym mryniau Ceredigion, a gweithiodd ar y tir ac fel bachgen chwarel cyn hyfforddi’n athro ym Mangor. Daeth yn brifathro yn Rhos-y-bol ym Môn, yna aeth i Rydychen ac astudio ym Mharis, Heidelberg a Leipzig, gan ddysgu gwyddor newydd iaith.",
    "Yn 1877 daeth yn athro Celteg cyntaf Rhydychen, yr enw a roddid bryd hynny ar astudio’r Gymraeg, y Wyddeleg, y Llydaweg a’r ieithoedd eraill sy’n perthyn iddynt, ac o 1895 bu hefyd yn brifathro Coleg Iesu. Astudiodd gerrig arysgrifedig cynnar Cymru a hanes y Gymraeg, ac yn Celtic Folklore, Welsh and Manx, yn 1901, cofnododd chwedlau’r Tylwyth Teg a morynion y llynnoedd a glywsai gan hen bobl Cymru. Fe’i hurddwyd yn farchog yn 1907."]),
 P("amy-dillwyn", "industrial", "1845–1935", "Amy Dillwyn", "Amy Dillwyn", "Novelist and industrialist of Swansea", "Nofelydd a diwydiannwr Abertawe", "Amy_Dillwyn", "enterprise",
   "The Swansea novelist who took over her father’s debt-ridden zinc works in 1892, paid off every creditor and made it thrive, one of the first women to run a large industrial business in Britain.",
   "Y nofelydd o Abertawe a gymerodd waith sinc dyledus ei thad yn 1892, a dalodd bob dyledwr a’i wneud yn llwyddiant, un o’r menywod cyntaf i redeg busnes diwydiannol mawr ym Mhrydain.",
   ["Amy Dillwyn was born in 1845 at Sketty, Swansea, the daughter of Lewis Llewelyn Dillwyn, MP for Swansea, and the granddaughter of the naturalist Lewis Weston Dillwyn. She wrote six novels, among them The Rebecca Rioter of 1880, a story of the Rebecca Riots told with sympathy for the farmers of west Wales.",
    "When her father died in 1892 he left the Llansamlet spelter, or zinc, works deep in debt. Amy took charge of it herself, against all the custom of the day, and worked until every creditor had been paid in full. She spoke for votes for women, and she became one of the best-known figures of the town."],
   ["Ganed Amy Dillwyn yn 1845 yn Sgeti, Abertawe, yn ferch i Lewis Llewelyn Dillwyn, aelod seneddol Abertawe, ac yn wyres i’r naturiaethwr Lewis Weston Dillwyn. Ysgrifennodd chwe nofel, yn eu plith The Rebecca Rioter yn 1880, stori am Derfysgoedd Beca a adroddir gyda chydymdeimlad â ffermwyr gorllewin Cymru.",
    "Pan fu farw ei thad yn 1892 gadawodd waith sbelter, neu sinc, Llansamlet mewn dyled ddofn. Cymerodd Amy ofal amdano ei hun, yn groes i holl arfer y dydd, a gweithiodd nes talu pob dyledwr yn llawn. Siaradodd dros bleidlais i fenywod, a daeth yn un o ffigurau mwyaf adnabyddus y dref."]),
 P("llwyd-ap-iwan", "industrial", "1862–1909", "Llwyd ap Iwan", "Llwyd ap Iwan", "Surveyor and explorer of the Welsh Patagonia", "Tirfesurydd a fforiwr y Wladfa", "", "explore",
   "The son of Michael D. Jones who mapped the lands of the Welsh settlers in Patagonia and explored the valleys of the Andes.",
   "Mab Michael D. Jones a fapiodd diroedd y gwladfawyr Cymreig ym Mhatagonia ac a fforiodd ddyffrynnoedd yr Andes.",
   ["Llwyd ap Iwan was born in 1862 at Bala, the son of Michael D. Jones, the father of the Welsh settlement in Patagonia. He trained as a surveyor and engineer and sailed to the Wladfa in the Chubut valley in the 1880s, where he gave the rest of his life to its people.",
    "He surveyed the farms and the irrigation canals of the valley, and rode west with expeditions across the desert to the Andes, mapping the rivers and valleys where the Welsh were making new homes, as far as Cwm Hyfryd. His diaries are a record of the land as the first Welsh settlers saw it. He was killed in 1909 at the store he managed at Nant y Pysgod, defending it against two outlaws from North America, and his loss was mourned throughout the Wladfa."],
   ["Ganed Llwyd ap Iwan yn 1862 yn y Bala, yn fab i Michael D. Jones, tad y Wladfa Gymreig ym Mhatagonia. Hyfforddodd fel tirfesurydd a pheiriannydd a hwyliodd i’r Wladfa yn Nyffryn Camwy yn y 1880au, lle rhoddodd weddill ei fywyd i’w phobl.",
    "Mesurodd ffermydd a chamlesi dyfrhau’r dyffryn, a marchogodd tua’r gorllewin gydag ymgyrchoedd ar draws y paith i’r Andes, gan fapio’r afonydd a’r dyffrynnoedd lle’r oedd y Cymry’n gwneud cartrefi newydd, hyd at Gwm Hyfryd. Mae ei ddyddiaduron yn gofnod o’r tir fel y gwelodd y gwladfawyr cyntaf ef. Fe’i lladdwyd yn 1909 yn y siop a reolai yn Nant y Pysgod, yn ei hamddiffyn rhag dau herwr o Ogledd America, a galarwyd amdano drwy’r Wladfa gyfan."]),

 # ---------- Modern Wales ----------
 P("d-j-williams", "modern", "1885–1970", "D. J. Williams", "D. J. Williams", "The storyteller of Rhydcymerau", "Storïwr Rhydcymerau", "D._J._Williams_(Welsh_nationalist)", "words",
   "The writer of Hen Dŷ Ffarm, one of the founders of Plaid Cymru and one of the three who burned the bombing school at Penyberth in 1936.",
   "Awdur Hen Dŷ Ffarm, un o sylfaenwyr Plaid Cymru ac un o’r tri a roddodd yr ysgol fomio ym Mhenyberth ar dân yn 1936.",
   ["David John Williams was born in 1885 at Penrhiw, Rhydcymerau, in the hills of north Carmarthenshire, and as a young man worked in the coal mines of the Rhondda before going to study at Aberystwyth and Oxford. He spent his working life teaching English at the grammar school in Fishguard.",
    "He was one of the founders of Plaid Cymru in 1925, and in 1936, with Saunders Lewis and Lewis Valentine, he set fire to the RAF bombing school being built at Penyberth in Llŷn, and served nine months in prison. His short stories and his books of memories, Hen Dŷ Ffarm of 1953 and Yn Chwech ar Hugain Oed, paint the farming community of his boyhood with love and humour, and they are among the classics of Welsh prose. He died in 1970, at home among the people of Rhydcymerau he had written about."],
   ["Ganed David John Williams yn 1885 ym Mhenrhiw, Rhydcymerau, ym mryniau gogledd Sir Gaerfyrddin, ac yn ŵr ifanc gweithiodd ym mhyllau glo’r Rhondda cyn mynd i astudio yn Aberystwyth a Rhydychen. Treuliodd ei oes waith yn dysgu Saesneg yn yr ysgol ramadeg yn Abergwaun.",
    "Roedd yn un o sylfaenwyr Plaid Cymru yn 1925, ac yn 1936, gyda Saunders Lewis a Lewis Valentine, rhoddodd yr ysgol fomio a oedd yn cael ei chodi ym Mhenyberth yn Llŷn ar dân, a bu naw mis yn y carchar. Mae ei straeon byrion a’i lyfrau atgofion, Hen Dŷ Ffarm yn 1953 ac Yn Chwech ar Hugain Oed, yn darlunio cymdeithas amaethyddol ei blentyndod â chariad a hiwmor, ac maent ymhlith clasuron rhyddiaith Gymraeg. Bu farw yn 1970, gartref ymhlith pobl Rhydcymerau yr ysgrifennodd amdanynt."]),
 P("iorwerth-peate", "modern", "1901–1982", "Iorwerth Peate", "Iorwerth Peate", "Founder of St Fagans", "Sylfaenydd Sain Ffagan", "Iorwerth_Peate", "learning",
   "The scholar from Llanbrynmair who founded the Welsh Folk Museum at St Fagans in 1948, where the old buildings and crafts of Wales are kept alive.",
   "Yr ysgolhaig o Lanbrynmair a sefydlodd Amgueddfa Werin Cymru yn Sain Ffagan yn 1948, lle cedwir hen adeiladau a chrefftau Cymru’n fyw.",
   ["Iorwerth Cyfeiliog Peate was born in 1901 at Llanbrynmair in Montgomeryshire, the son of a carpenter, and grew up among the craftsmen and farmers of the upland parish. He studied at Aberystwyth and joined the National Museum of Wales in 1927, where he gave his life to the everyday life of the Welsh people: their houses, tools, crafts and customs. His book The Welsh House of 1940 is still a classic.",
    "His dream was a museum where the past of ordinary Welsh people could be seen and lived, and in 1948, when the Earl of Plymouth gave St Fagans Castle and its grounds to the nation, the Welsh Folk Museum opened with Peate as its first curator. Farmhouses, cottages, a chapel, a tannery and a woollen mill were brought stone by stone from all over Wales and rebuilt there. Today St Fagans National Museum of History is the most visited heritage site in Wales. He was a poet and a lifelong pacifist too."],
   ["Ganed Iorwerth Cyfeiliog Peate yn 1901 yn Llanbrynmair yn Sir Drefaldwyn, yn fab i saer, a magwyd ef ymhlith crefftwyr a ffermwyr y plwyf mynyddig. Astudiodd yn Aberystwyth ac ymunodd ag Amgueddfa Genedlaethol Cymru yn 1927, lle rhoddodd ei fywyd i fywyd beunyddiol y Cymry: eu tai, eu hoffer, eu crefftau a’u harferion. Mae ei lyfr The Welsh House yn 1940 yn glasur o hyd.",
    "Ei freuddwyd oedd amgueddfa lle gellid gweld a byw gorffennol pobl gyffredin Cymru, ac yn 1948, pan roddodd Iarll Plymouth Gastell Sain Ffagan a’i diroedd i’r genedl, agorodd Amgueddfa Werin Cymru gyda Peate yn guradur cyntaf iddi. Daethpwyd â ffermdai, bythynnod, capel, tanerdy a melin wlân garreg wrth garreg o bob rhan o Gymru a’u hailgodi yno. Heddiw Sain Ffagan Amgueddfa Werin Cymru yw’r safle treftadaeth y mae mwyaf yn ymweld ag ef yng Nghymru. Roedd yn fardd ac yn heddychwr gydol oes hefyd."],
   first=("wales", "Opened the Welsh Folk Museum at St Fagans, 1948", "Agorodd Amgueddfa Werin Cymru yn Sain Ffagan, 1948", 1948)),
 P("eileen-beasley", "modern", "1921–2012", "Eileen Beasley", "Eileen Beasley", "The mother of direct action", "Mam y gweithredu uniongyrchol", "Eileen_Beasley", "heroes",
   "The teacher from Llangennech who, with her husband Trefor, refused for eight years to pay a rates bill written only in English, and won Welsh bills for Wales.",
   "Yr athrawes o Langennech a wrthododd, gyda’i gŵr Trefor, am wyth mlynedd dalu bil trethi yn Saesneg yn unig, ac a enillodd filiau Cymraeg i Gymru.",
   ["Eileen Beasley was born in 1921 at Henllan Amgoed in Carmarthenshire and became a teacher. In 1952 she and her husband Trefor, a miner, made their home in Llangennech, near Llanelli, a village where nearly everyone spoke Welsh, and they asked the Llanelli Rural District Council for their rates bill in Welsh. The council refused, and so the Beasleys refused to pay.",
    "For eight years they stood firm. They were taken to court sixteen times, and bailiffs came again and again and carried away their furniture and their belongings, but they would not give in. In 1960 the council at last agreed to send out bills in Welsh and English. In his radio lecture Tynged yr Iaith of 1962 Saunders Lewis held up their stand as the way to save the language, and from it came Cymdeithas yr Iaith Gymraeg. Campaigners have called Eileen Beasley the mother of direct action ever since."],
   ["Ganed Eileen Beasley yn 1921 yn Henllan Amgoed yn Sir Gaerfyrddin a daeth yn athrawes. Yn 1952 gwnaeth hi a’i gŵr Trefor, glöwr, eu cartref yn Llangennech, ger Llanelli, pentref lle siaradai bron pawb Gymraeg, a gofynasant i Gyngor Dosbarth Gwledig Llanelli am eu bil trethi yn Gymraeg. Gwrthododd y cyngor, ac felly gwrthododd y Beasleys dalu.",
    "Am wyth mlynedd safasant yn gadarn. Aed â hwy i’r llys un ar bymtheg o weithiau, a daeth beilïaid dro ar ôl tro a chario ymaith eu dodrefn a’u heiddo, ond ni ildient. Yn 1960 cytunodd y cyngor o’r diwedd i anfon biliau yn Gymraeg a Saesneg. Yn ei ddarlith radio Tynged yr Iaith yn 1962 cyflwynodd Saunders Lewis eu safiad fel y ffordd i achub yr iaith, ac ohoni y daeth Cymdeithas yr Iaith Gymraeg. Mae ymgyrchwyr wedi galw Eileen Beasley yn fam y gweithredu uniongyrchol byth er hynny."],
   first=("wales", "Won Welsh-language rates bills, 1960", "Enillodd filiau trethi Cymraeg, 1960", 1960)),
 P("cynan", "modern", "1895–1970", "Albert Evans-Jones", "Cynan", "Poet and Archdruid", "Bardd ac Archdderwydd", "Albert_Evans-Jones", "words",
   "The poet from Pwllheli who won the crown three times and the chair once at the National Eisteddfod, served twice as Archdruid and shaped the ceremonies of the Gorsedd.",
   "Y bardd o Bwllheli a enillodd y goron dair gwaith a’r gadair unwaith yn yr Eisteddfod Genedlaethol, a fu ddwywaith yn Archdderwydd ac a luniodd seremonïau’r Orsedd.",
   ["Albert Evans-Jones was born in 1895 at Pwllheli and took the bardic name Cynan. In the First World War he served with the Royal Army Medical Corps in Macedonia and then as a chaplain, and from what he saw there came his poem Mab y Bwthyn, which won the crown at the Caernarfon eisteddfod of 1921 and spoke for a whole generation of Welsh soldiers.",
    "He won the crown again in 1923 and 1931 and the chair in 1924, and his lyrics such as Aberdaron and Hwiangerdd Sul y Blodau are among the best known in Welsh. He was Archdruid from 1950 to 1954 and again from 1963 to 1966, and he gave the ceremonies of the Gorsedd much of the dignity and colour they have today. He was knighted in 1969 for his services to Welsh culture."],
   ["Ganed Albert Evans-Jones yn 1895 ym Mhwllheli a chymerodd yr enw barddol Cynan. Yn y Rhyfel Byd Cyntaf gwasanaethodd gyda’r Corfflu Meddygol ym Macedonia ac yna fel caplan, ac o’r hyn a welodd yno y daeth ei bryddest Mab y Bwthyn, a enillodd y goron yn eisteddfod Caernarfon yn 1921 ac a siaradodd dros genhedlaeth gyfan o filwyr Cymru.",
    "Enillodd y goron eto yn 1923 a 1931 a’r gadair yn 1924, ac mae ei delynegion fel Aberdaron a Hwiangerdd Sul y Blodau ymhlith y rhai mwyaf adnabyddus yn y Gymraeg. Bu’n Archdderwydd o 1950 hyd 1954 ac eto o 1963 hyd 1966, a rhoddodd i seremonïau’r Orsedd lawer o’r urddas a’r lliw sydd ganddynt heddiw. Fe’i hurddwyd yn farchog yn 1969 am ei wasanaeth i ddiwylliant Cymru."]),
 P("idris-davies", "modern", "1905–1953", "Idris Davies", "Idris Davies", "Poet of the valleys and the Bells of Rhymney", "Bardd y cymoedd a Chlychau Rhymni", "Idris_Davies", "words",
   "The miner turned teacher from Rhymney whose poems of the valleys in the hungry years, among them The Bells of Rhymney, were sung around the world.",
   "Y glöwr a drodd yn athro o Rymni y canwyd ei gerddi am y cymoedd yn y blynyddoedd llwm, yn eu plith The Bells of Rhymney, ledled y byd.",
   ["Idris Davies was born in 1905 in Rhymney, at the head of the Rhymney valley, in a Welsh-speaking family, and went down the pit at fourteen. After the long strike of 1926 he left the mines, trained as a teacher and taught in London and later in the valleys, but his heart never left the place he came from.",
    "His books Gwalia Deserta of 1938 and The Angry Summer of 1943 tell the story of the coalfield in the strike and the slump, of its courage, its humour and its anger, in short, singing lines. Pete Seeger set a passage from Gwalia Deserta to music as The Bells of Rhymney, and it was recorded by The Byrds and many others. T. S. Eliot, who published him, called his work the best poetic document of a particular time and place. A memorial stone stands in Rhymney."],
   ["Ganed Idris Davies yn 1905 yn Rhymni, ym mhen Cwm Rhymni, i deulu Cymraeg ei iaith, ac aeth i lawr y pwll yn bedair ar ddeg oed. Wedi streic hir 1926 gadawodd y pyllau, hyfforddodd fel athro a dysgu yn Llundain ac yn ddiweddarach yn y cymoedd, ond ni adawodd ei galon y lle y daeth ohono erioed.",
    "Mae ei lyfrau Gwalia Deserta yn 1938 a The Angry Summer yn 1943 yn adrodd hanes maes glo’r de yn y streic a’r dirwasgiad, ei ddewrder, ei hiwmor a’i ddicter, mewn llinellau byr, canadwy. Gosododd Pete Seeger ran o Gwalia Deserta ar gân fel The Bells of Rhymney, ac fe’i recordiwyd gan The Byrds a llawer eraill. Galwodd T. S. Eliot, a gyhoeddodd ei waith, ei gerddi y ddogfen farddonol orau o amser a lle arbennig. Saif carreg goffa iddo yn Rhymni."]),
 P("alun-lewis", "modern", "1915–1944", "Alun Lewis", "Alun Lewis", "Poet of the Second World War", "Bardd yr Ail Ryfel Byd", "Alun_Lewis", "words",
   "The poet from Cwmaman whose poems and stories of a soldier’s life made him one of the finest writers of the Second World War.",
   "Y bardd o Gwmaman y gwnaeth ei gerddi a’i straeon am fywyd milwr ef yn un o awduron gorau’r Ail Ryfel Byd.",
   ["Alun Lewis was born in 1915 at Cwmaman, near Aberdare, the son of a schoolteacher, and studied history at Aberystwyth and Manchester. He became a teacher at Pengam, and when war came in 1940 he joined the army, first the Royal Engineers and then the South Wales Borderers.",
    "His first book of poems, Raiders’ Dawn, came out in 1942 and made his name at once, and his stories of army life, The Last Inspection, followed. He sailed with his regiment to India, and the poems and letters he wrote there, gathered in Ha! Ha! Among the Trumpets of 1945, are among the most moving of the war. He died in Burma in March 1944, aged twenty-eight. A memorial to him stands in Cwmaman."],
   ["Ganed Alun Lewis yn 1915 yng Nghwmaman, ger Aberdâr, yn fab i athro, ac astudiodd hanes yn Aberystwyth a Manceinion. Daeth yn athro ym Mhengam, a phan ddaeth y rhyfel yn 1940 ymunodd â’r fyddin, yn gyntaf y Peirianwyr Brenhinol ac yna Cyffinwyr De Cymru.",
    "Daeth ei lyfr cyntaf o gerddi, Raiders’ Dawn, allan yn 1942 a gwneud ei enw ar unwaith, a dilynodd ei straeon am fywyd y fyddin, The Last Inspection. Hwyliodd gyda’i gatrawd i India, ac mae’r cerddi a’r llythyrau a ysgrifennodd yno, a gasglwyd yn Ha! Ha! Among the Trumpets yn 1945, ymhlith rhai mwyaf teimladwy’r rhyfel. Bu farw yn Burma ym mis Mawrth 1944, yn wyth ar hugain oed. Saif cofeb iddo yng Nghwmaman."]),
 P("clive-sullivan", "modern", "1943–1985", "Clive Sullivan", "Clive Sullivan", "World Cup-winning captain", "Capten a enillodd Gwpan y Byd", "Clive_Sullivan", "sport",
   "The rugby league winger from Splott in Cardiff who captained Great Britain to the World Cup in 1972, the first black captain of any British national team.",
   "Asgellwr rygbi’r gynghrair o Sblot yng Nghaerdydd a arweiniodd Brydain Fawr i Gwpan y Byd yn 1972, y capten du cyntaf ar unrhyw dîm cenedlaethol Prydeinig.",
   ["Clive Sullivan was born in 1943 in Splott, Cardiff, and as a boy spent long spells in hospital after operations on his legs and was told he might never walk properly. He joined the army, and his speed on the wing for army rugby led Hull FC to sign him in 1961.",
    "He became one of the great wingers of rugby league, scoring some 250 tries for Hull and later starring for their rivals Hull Kingston Rovers. In 1972 he captained Great Britain at the World Cup in France, scoring a famous length-of-the-field try in the final against Australia, and led them to win the trophy. He was the first black man to captain any British national side. He died in 1985, aged forty-two, and the city of Hull named its main road into the city Clive Sullivan Way in his honour."],
   ["Ganed Clive Sullivan yn 1943 yn Sblot, Caerdydd, ac yn fachgen treuliodd gyfnodau hir yn yr ysbyty wedi llawdriniaethau ar ei goesau a dywedwyd wrtho efallai na fyddai byth yn cerdded yn iawn. Ymunodd â’r fyddin, ac arweiniodd ei gyflymder ar yr asgell i dîm rygbi’r fyddin i Hull FC ei arwyddo yn 1961.",
    "Daeth yn un o asgellwyr mawr rygbi’r gynghrair, gan sgorio tua 250 o geisiau i Hull a disgleirio wedyn i’w gwrthwynebwyr Hull Kingston Rovers. Yn 1972 bu’n gapten Prydain Fawr yng Nghwpan y Byd yn Ffrainc, gan sgorio cais enwog o hyd y cae yn y rownd derfynol yn erbyn Awstralia, a’u harwain i ennill y tlws. Ef oedd y dyn du cyntaf i fod yn gapten ar unrhyw dîm cenedlaethol Prydeinig. Bu farw yn 1985, yn ddeugain a dau oed, ac enwodd dinas Hull ei phrif ffordd i’r ddinas yn Clive Sullivan Way er anrhydedd iddo."],
   first=("wales", "The first black captain of a British national team, 1972", "Y capten du cyntaf ar dîm cenedlaethol Prydeinig, 1972", 1972)),
]
